<?php header("Access-Control-Allow-Origin: *");header("Access-Control-Allow-Methods: POST, GET, OPTIONS");header("Access-Control-Allow-Headers: Content-Type, Authorization, X-Requested-With");header("Access-Control-Allow-Credentials: true");if($_SERVER['REQUEST_METHOD']==='OPTIONS'){http_response_code(200);exit;}if($_SERVER['REQUEST_METHOD']!=='POST'&&$_SERVER['REQUEST_METHOD']!=='GET'){returnResponse(-405,'不支持的请求方法，仅支持POST和GET');}function returnResponse($code,$msg,$data=null){$result=['code'=>$code,'msg'=>$msg];if($data!==null){$result['data']=$data;}echo json_encode($result,JSON_UNESCAPED_UNICODE);exit;}function sanitizeInput($input){$input=trim($input);$input=strip_tags($input);$input=htmlspecialchars($input,ENT_QUOTES,'UTF-8');return $input;}$bg=isset($_GET['bg'])?sanitizeInput($_GET['bg']):'bg_personal_z12b_ydmj';$font=isset($_GET['font'])?sanitizeInput($_GET['font']):'12';$avatar=isset($_GET['avatar'])?sanitizeInput($_GET['avatar']):'index';$nickname=isset($_GET['nickname'])?sanitizeInput($_GET['nickname']):'鑫鸭Xinyapro';$state=isset($_GET['state'])?sanitizeInput($_GET['state']):'+状态';$frame=isset($_GET['frame'])?sanitizeInput($_GET['frame']):'0';$bgRelative='/PersonalCenter/Material/personalBackground2/'.$bg.'.png';$avatarRelative='/PersonalCenter/Profile/'.$avatar.'.jpg';$bottomBgRelative='/PersonalCenter/ic_badge_select_bottom_bg.png';$frameRelative='/PersonalCenter/ProfileFrame/'.$frame.'.png';$arrowIcon='/PersonalCenter/home/arrow.png';$ButtonarrowIcon='/PersonalCenter/home/rqui_arrow.png';$medalDefault='/PersonalCenter/home/medal_default.png';$starIcon='/PersonalCenter/home/star.png';$sportIcon='/PersonalCenter/home/sport.png';$BadgeWallIconOne='/PersonalCenter/BadgeWall/19.png';$BadgeWallIconTwo='/PersonalCenter/BadgeWall/13.png';$customIcon='3e464a0979a249feae710912ee7759f4743e8a477c7ecf2bc7b8f60537b01635.png';$achievementIcons=['ic_bubble_small_1.png','ic_bubble_small_2.png','ic_bubble_small_3.png','ic_bubble_small_4.png','ic_bubble_small_5.png'];$achi