q-content"><span class="q-list-text">更多</span></div><img class="q-icon" src="<?php echo $ButtonarrowIcon; ?>" alt="arrow"></div><div class="scroll-spacer"></div></div></div></div><input type="file" id="fileInput" accept="image/*" style="display:none"><script>document.getElementById('avatarUpload').addEventListener('click',function(){document.getElementById('fileInput').click();});document.getElementById('fileInput').addEventListener('change',function(e){const file=e.target.files[0];if(file){const reader=new FileReader();reader.onload=function(event){document.getElementById('avatarImg').src=event.target.result;};reader.readAsDataURL(file);}});</script></body></html>